 private class NeonBackground extends View {private final Paint paint=new Paint(3);NeonBackground(){super(MainActivity.this);}protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(Color.BLACK);float w=getWidth(),h=getHeight();float[][] lines={{-.25f,.45f},{.03f,.73f},{.66f,1.36f},{1.02f,1.72f}};for(float[] line:lines){for(int k=7;k>=0;k--){paint.setColor(Color.argb(k==0?235:12,255,5,35));paint.setStrokeWidth(dp(k==0?2:k*5));c.drawLine(w*line[0],h,w*line[1],0,paint);}}paint.setShader(new RadialGradient(w*.35f,h*.43f,Math.max(w,h)*.6f,new int[]{0x393c000b,0x00000000},null,Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,paint);paint.setShader(null);}}
